CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, units TEXT NOT NULL CHECK(units='m'), created_at TEXT NOT NULL, is_demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE source_artifacts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), storage_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE analysis_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), artifact_id TEXT NOT NULL REFERENCES source_artifacts(id), status TEXT NOT NULL, stage TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE analysis_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES analysis_runs(id), stage TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE home_scenes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), current_version INTEGER NOT NULL);
CREATE TABLE scene_versions (id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES home_scenes(id), version INTEGER NOT NULL CHECK(version>0), parent_version INTEGER, restored_from INTEGER, summary TEXT NOT NULL, created_at TEXT NOT NULL, schema_version INTEGER NOT NULL, units TEXT NOT NULL CHECK(units='m'), UNIQUE(scene_id,version));
CREATE TABLE floors (version_id TEXT NOT NULL REFERENCES scene_versions(id), id TEXT NOT NULL, name TEXT NOT NULL, elevation REAL, scale_json TEXT NOT NULL, PRIMARY KEY(version_id,id));
CREATE TABLE entities (version_id TEXT NOT NULL, floor_id TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL, host_wall_id TEXT, left_room_id TEXT, right_room_id TEXT, from_room_id TEXT, to_room_id TEXT, data_json TEXT NOT NULL, PRIMARY KEY(version_id,id), UNIQUE(version_id,floor_id,id), FOREIGN KEY(version_id,floor_id) REFERENCES floors(version_id,id), FOREIGN KEY(version_id,floor_id,host_wall_id) REFERENCES entities(version_id,floor_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(version_id,floor_id,left_room_id) REFERENCES entities(version_id,floor_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(version_id,floor_id,right_room_id) REFERENCES entities(version_id,floor_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(version_id,floor_id,from_room_id) REFERENCES entities(version_id,floor_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(version_id,floor_id,to_room_id) REFERENCES entities(version_id,floor_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE evidence (version_id TEXT NOT NULL REFERENCES scene_versions(id), id TEXT NOT NULL, source_artifact_id TEXT REFERENCES source_artifacts(id), data_json TEXT NOT NULL, PRIMARY KEY(version_id,id));
CREATE TABLE entity_evidence (version_id TEXT NOT NULL, entity_id TEXT NOT NULL, evidence_id TEXT NOT NULL, PRIMARY KEY(version_id,entity_id,evidence_id), FOREIGN KEY(version_id,entity_id) REFERENCES entities(version_id,id), FOREIGN KEY(version_id,evidence_id) REFERENCES evidence(version_id,id));
CREATE TABLE corrections (id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES home_scenes(id), entity_id TEXT NOT NULL, version INTEGER NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE verifications (id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES home_scenes(id), entity_id TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE clarifications (id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES home_scenes(id), entity_id TEXT, priority INTEGER NOT NULL, question TEXT NOT NULL, answer TEXT);
CREATE INDEX entities_floor ON entities(version_id,floor_id,kind);
CREATE INDEX versions_scene ON scene_versions(scene_id,version);
CREATE INDEX artifacts_project ON source_artifacts(project_id);
